'use client';

import { useModalContext } from '@/lib/modal-context';
import { cn } from '@/lib/utils';

export function ModalRenderer() {
  const { modals, closeModal } = useModalContext();

  if (modals.length === 0) {
    return null;
  }

  return (
    <>
      {modals.map((modal) => {
        const Component = modal.component;

        const handleOverlayClick = () => {
          if (modal.settings.closeOnOverlayClick) {
            closeModal(modal.id);
          }
        };

        const handleClose = (result?: unknown) => {
          closeModal(modal.id, result);
        };

        return (
          <div key={modal.id} role="dialog" aria-modal="true">
            {/* Overlay */}
            <div
              className={cn(
                'fixed inset-0 bg-black/50',
                'animate-in fade-in-0 duration-200'
              )}
              style={{ zIndex: modal.zIndex }}
              onClick={handleOverlayClick}
              aria-hidden="true"
            />

            {/* Modal content wrapper */}
            <div
              className={cn(
                'fixed inset-0 pointer-events-none',
                // Mobile: align to bottom for bottom sheet
                'flex items-end justify-center',
                // Desktop: center vertically for modal
                'md:items-center',
                // Prevent scroll chaining to background
                'overscroll-contain'
              )}
              style={{ zIndex: modal.zIndex + 1 }}
            >
              <div
                className={cn(
                  'pointer-events-auto',
                  // Mobile: full width bottom sheet with slide-up animation
                  'w-full animate-in fade-in-0 slide-in-from-bottom duration-300',
                  // Desktop: auto width modal with zoom animation
                  'md:w-auto md:slide-in-from-bottom-0 md:zoom-in-95 md:duration-200'
                )}
                onClick={(e) => e.stopPropagation()}
              >
                <Component
                  {...modal.props}
                  isOpen={true}
                  onClose={handleClose}
                />
              </div>
            </div>
          </div>
        );
      })}
    </>
  );
}
