'use client';

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useEffect,
  ReactNode,
} from 'react';
import type {
  ModalContextValue,
  ModalInstance,
  ModalConfig,
  BaseModalProps,
  ModalCallbacks,
} from '@/types/modal';

// Z-index configuration for modal stacking
const BASE_MODAL_Z_INDEX = 100;
const Z_INDEX_INCREMENT = 10;

// Generate unique modal IDs
let modalIdCounter = 0;
function generateModalId(): string {
  return `modal-${++modalIdCounter}-${Date.now()}`;
}

const ModalContext = createContext<ModalContextValue | undefined>(undefined);

export function ModalProvider({ children }: { children: ReactNode }) {
  const [modals, setModals] = useState<ModalInstance[]>([]);

  // Handle body scroll lock when modals are open
  useEffect(() => {
    if (modals.length > 0) {
      // Capture current scroll position before locking
      const scrollY = window.scrollY;
      const scrollbarWidth =
        window.innerWidth - document.documentElement.clientWidth;

      // Lock body scroll (position fixed prevents iOS Safari scroll)
      document.body.style.position = 'fixed';
      document.body.style.top = `-${scrollY}px`;
      document.body.style.width = '100%';
      document.body.style.overflow = 'hidden';
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    } else {
      // Restore scroll position when closing
      const scrollY = document.body.style.top;
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
      document.body.style.overflow = '';
      document.body.style.paddingRight = '';

      // Restore scroll position
      window.scrollTo(0, parseInt(scrollY || '0') * -1);
    }

    return () => {
      const scrollY = document.body.style.top;
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
      document.body.style.overflow = '';
      document.body.style.paddingRight = '';

      if (scrollY) {
        window.scrollTo(0, parseInt(scrollY) * -1);
      }
    };
  }, [modals.length]);

  const closeModal = useCallback((id: string, result?: unknown) => {
    setModals((prev) => {
      const modalIndex = prev.findIndex((m) => m.id === id);
      if (modalIndex === -1) return prev;

      const modal = prev[modalIndex];
      // Call onClose callback with result
      (modal.callbacks as ModalCallbacks<unknown>).onClose?.(result);

      return prev.filter((m) => m.id !== id);
    });
  }, []);

  // Handle escape key to close the topmost modal
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && modals.length > 0) {
        const topModal = modals[modals.length - 1];
        if (topModal.settings.closeOnEscape) {
          closeModal(topModal.id);
        }
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [modals, closeModal]);

  const openModal = useCallback(
    <TProps extends BaseModalProps, TResult = void>(
      config: ModalConfig<TProps, TResult>
    ): string => {
      const id = generateModalId();

      setModals((prev) => {
        const zIndex = BASE_MODAL_Z_INDEX + prev.length * Z_INDEX_INCREMENT;

        const instance: ModalInstance = {
          id,
          component: config.component as ModalInstance['component'],
          props: (config.props || {}) as Record<string, unknown>,
          callbacks: (config.callbacks || {}) as ModalCallbacks<unknown>,
          settings: {
            closeOnOverlayClick: config.settings?.closeOnOverlayClick ?? true,
            closeOnEscape: config.settings?.closeOnEscape ?? true,
          },
          zIndex,
        };

        // Call onOpen callback
        config.callbacks?.onOpen?.();

        return [...prev, instance];
      });

      return id;
    },
    []
  );

  const closeAllModals = useCallback(() => {
    setModals((prev) => {
      // Call onClose for each modal in reverse order (top to bottom)
      [...prev].reverse().forEach((modal) => {
        (modal.callbacks as ModalCallbacks<unknown>).onClose?.();
      });
      return [];
    });
  }, []);

  const value: ModalContextValue = {
    modals,
    openModal,
    closeModal,
    closeAllModals,
  };

  return (
    <ModalContext.Provider value={value}>{children}</ModalContext.Provider>
  );
}

export function useModalContext(): ModalContextValue {
  const context = useContext(ModalContext);
  if (context === undefined) {
    throw new Error('useModalContext must be used within a ModalProvider');
  }
  return context;
}
